PI=math.pi
def T(en,ur=None,ps=None):return f'{en} || {ur or en} || {ps or en}'
def P(en,ur,ps):return f'p {T(en,ur,ps)}\n'
def EX(n,en,ur,ps):return f'example {n} | {T(en,ur,ps)}\n'
SOL=P('**Solution:**','**حل:**','**حل:**')
def S(w,h,aria,body):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{aria}"><title>{aria}</title>{body}</svg>'
tx=lambda x,y,t,sz=12,fill='#0f172a':f'<text x="{x}" y="{y}" font-size="{sz}" fill="{fill}" font-family="sans-serif">{t}</text>'
def wave(fn,x0,x1,aria,ymax=1.3,w=560,h=230,labels=None,asym=(),col='#2563eb',lw=2.4,yl=(1,-1),pad=40,hl=()):
    X=lambda v:pad+(v-x0)/(x1-x0)*(w-pad-20)
    Y=lambda v:h/2-v/ymax*(h/2-24)
    ax=X(0) if x0<=0<=x1 else pad
    o=f'<path d="M{pad-10} {Y(0):.1f}H{w-10}M{ax:.1f} {h-8}V8" stroke="#334155" stroke-width="1.5" fill="none"/><path d="M{w-10} {Y(0):.1f}l-8-4v8Z" fill="#334155"/>'
    o+=tx(ax+6,Y(yl[0])+4,str(yl[0]),11)+tx(ax+6,Y(yl[1])+4,str(yl[1]),11)
    for v in hl:o+=f'<path d="M{pad-10} {Y(v):.1f}H{w-10}" stroke="#94a3b8" stroke-dasharray="3 4"/>'
    if labels:
        for v,t in labels:o+=f'<path d="M{X(v):.1f} {Y(0)-4:.1f}v8" stroke="#334155"/>'+tx(X(v)-10,Y(0)+18,t,11)
    segs=[(x0,x1)]
    if asym:
        pts=sorted([x0]+list(asym)+[x1]);segs=[(a+1e-3,b-1e-3) for a,b in zip(pts[:-1],pts[1:])]
        for a in asym:o+=f'<path d="M{X(a):.1f} 6V{h-6}" stroke="#94a3b8" stroke-dasharray="4 4"/>'
    for a,b in segs:
        pts=[]
        for i in range(401):
            v=a+(b-a)*i/400
            try:y=fn(v)
            except ZeroDivisionError:continue
            if abs(y)<=ymax*1.05:pts.append(f'{"M" if not pts else "L"}{X(v):.1f} {Y(y):.1f}')
        if pts:o+=f'<path d="{" ".join(pts)}" fill="none" stroke="{col}" stroke-width="{lw}"/>'
    return S(w,h,aria,o)
def tb(cap,xs,ys):return f'table {cap}\nth | $x$ | '+' | '.join(xs)+'\ntr | $y$ | '+' | '.join(ys)+'\nendtable\n'
deg=lambda d:d*PI/180
