f1227=wave(lambda v:math.sin(2*v),-3.3*PI,3.3*PI,'Figure 12.27: the graph of y = sin 2 theta, two periods in an interval of length 2 pi',ymax=1.25,labels=[(PI,'π'),(2*PI,'2π'),(3*PI,'3π')],h=190)
